// slide-01.js — Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Large accent shape on the right side
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 0, w: 3.8, h: 5.625,
    fill: { color: theme.secondary, transparency: 40 }
  });

  // Decorative geometric elements
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.9, y: 0, w: 0.06, h: 5.625,
    fill: { color: theme.accent }
  });

  slide.addShape(pres.shapes.OVAL, {
    x: 7.0, y: 1.0, w: 2.2, h: 2.2,
    fill: { color: theme.accent, transparency: 70 },
    line: { color: theme.light, width: 2 }
  });

  slide.addShape(pres.shapes.OVAL, {
    x: 7.6, y: 3.2, w: 1.4, h: 1.4,
    fill: { color: theme.light, transparency: 60 },
    line: { color: theme.accent, width: 1.5 }
  });

  // Small decorative dots
  slide.addShape(pres.shapes.OVAL, {
    x: 6.5, y: 4.8, w: 0.15, h: 0.15,
    fill: { color: theme.accent }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.8, y: 5.0, w: 0.1, h: 0.1,
    fill: { color: theme.light }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 9.2, y: 0.3, w: 0.12, h: 0.12,
    fill: { color: theme.light }
  });

  // Title
  slide.addText("SkillClaw", {
    x: 0.6, y: 1.0, w: 5.0, h: 1.2,
    fontSize: 56, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left"
  });

  // Subtitle line 1
  slide.addText("Collective Skill Evolution for\nMulti-User LLM Agent Ecosystems", {
    x: 0.6, y: 2.2, w: 5.0, h: 1.0,
    fontSize: 22, fontFace: "Calibri",
    color: theme.light, align: "left", lineSpacingMultiple: 1.3
  });

  // Tagline
  slide.addText("Let Skills Evolve Collectively with Agentic Evolver", {
    x: 0.6, y: 3.4, w: 5.0, h: 0.5,
    fontSize: 16, fontFace: "Calibri",
    color: theme.accent, italic: true, align: "left"
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.15, w: 2.5, h: 0.04,
    fill: { color: theme.accent }
  });

  // Source reference
  slide.addText("arxiv.org/abs/2604.08377", {
    x: 0.6, y: 4.6, w: 5.0, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.light, transparency: 30, align: "left"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

