    fontSize: 18, fontFace: "Georgia",
    color: "2a9d8f", bold: true, align: "left"
  });

  slide.addText([
    { text: "Continuously updated from usage", options: { bullet: true, breakLine: true } },
    { text: "Cross-user evidence drives improvement", options: { bullet: true, breakLine: true } },
    { text: "Solutions persist and propagate", options: { bullet: true, breakLine: true } },
    { text: "Failures become evolution signals", options: { bullet: true, breakLine: true } },
    { text: "System-level knowledge accumulates", options: { bullet: true } }
  ], {
    x: 5.5, y: 2.3, w: 3.8, h: 2.3,
    fontSize: 13, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "top",
    paraSpaceAfter: 8
  });

  // Arrow between cards
  slide.addText("➡", {
    x: 4.55, y: 2.8, w: 0.9, h: 0.6,
    fontSize: 28, color: theme.accent, align: "center", valign: "middle"
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.0, w: 9.0, h: 0.45,
    fill: { color: theme.primary }
  });

  slide.addText("Memory-based methods stay instance-bound. Skill-based methods stay static. SkillClaw bridges both gaps.", {
