// slide-03.js — Architecture Overview (Process/Diagram subtype)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'timeline',
  index: 3,
  title: 'Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Closed-Loop Pipeline", {
    x: 0.5, y: 0.2, w: 9, h: 0.55,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  slide.addText("From Multi-User Interaction to Shared Skill Evolution", {
    x: 0.5, y: 0.7, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, italic: true, align: "left"
  });

  // --- MAIN DIAGRAM: Closed loop ---
  const centerX = 5.0;
  const centerY = 3.1;
  const loopW = 7.8;
  const loopH = 2.6;

  // Central label
  slide.addShape(pres.shapes.OVAL, {
    x: centerX - 0.8, y: centerY - 0.35, w: 1.6, h: 0.7,
    fill: { color: theme.primary }
  });
  slide.addText("SkillClaw\nClosed Loop", {
    x: centerX - 0.8, y: centerY - 0.35, w: 1.6, h: 0.7,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Stage positions (clockwise from top-left)
  const stages = [
    { label: "1. Evidence", desc: "Analyze trajectories\nfor behavioral patterns", x: 0.6, y: 1.3, color: theme.secondary },
    { label: "2. Attribution", desc: "Diagnose root causes\nof failures & successes", x: 3.5, y: 1.3, color: "2a9d8f" },
    { label: "3. Evolution", desc: "Propose skill mutations\n(refine or create new)", x: 6.4, y: 1.3, color: "e76f51" },
    { label: "4. Distribution", desc: "Verify, merge & synchronize\nskills to all agents", x: 3.5, y: 4.1, color: theme.accent }
  ];

  // Draw stage boxes
  stages.forEach((s, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: s.x, y: s.y, w: 2.5, h: 1.2,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.1 }
    });
    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: s.x, y: s.y, w: 2.5, h: 0.05,
      fill: { color: s.color }
    });
    // Stage label
    slide.addText(s.label, {
      x: s.x + 0.1, y: s.y + 0.1, w: 2.3, h: 0.35,
      fontSize: 14, fontFace: "Georgia",
      color: s.color, bold: true, align: "left"
    });
    // Stage description
    slide.addText(s.desc, {
      x: s.x + 0.1, y: s.y + 0.45, w: 2.3, h: 0.65,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, align: "left", valign: "top"
    });
  });

  // Arrows between stages
  // Evidence → Attribution
  slide.addShape(pres.shapes.LINE, {
    x: 3.1, y: 1.9, w: 0.4, h: 0,
    line: { color: theme.secondary, width: 2 }
  });
  slide.addText("▶", {
    x: 3.35, y: 1.75, w: 0.3, h: 0.3,
    fontSize: 12, color: theme.secondary, align: "center", valign: "middle"
  });

  // Attribution → Evolution
  slide.addShape(pres.shapes.LINE, {
    x: 6.0, y: 1.9, w: 0.4, h: 0,
    line: { color: "2a9d8f", width: 2 }
  });
  slide.addText("▶", {
    x: 6.25, y: 1.75, w: 0.3, h: 0.3,
    fontSize: 12, color: "2a9d8f", align: "center", valign: "middle"
  });

  // Evolution → Distribution (down and left)
  slide.addShape(pres.shapes.LINE, {
    x: 7.65, y: 2.5, w: 0, h: 1.1,
    line: { color: "e76f51", width: 2 }
  });
  slide.addShape(pres.shapes.LINE, {
    x: 6.0, y: 3.6, w: 1.65, h: 0,
    line: { color: "e76f51", width: 2 }
  });
  slide.addText("▶", {
    x: 5.8, y: 3.45, w: 0.3, h: 0.3,
    fontSize: 12, color: "e76f51", align: "center", valign: "middle"
  });

  // Distribution → Evidence (loop back left and up)
  slide.addShape(pres.shapes.LINE, {
    x: 3.5, y: 4.7, w: 0, h: 0.3,
    line: { color: theme.accent, width: 2 }
  });
  slide.addShape(pres.shapes.LINE, {
    x: 1.85, y: 5.0, w: 1.65, h: 0,
    line: { color: theme.accent, width: 2 }
  });
  slide.addShape(pres.shapes.LINE, {
    x: 1.85, y: 2.5, w: 0, h: 2.5,
    line: { color: theme.accent, width: 2 }
  });
  slide.addText("▲", {
    x: 1.7, y: 2.35, w: 0.3, h: 0.3,
    fontSize: 12, color: theme.accent, align: "center", valign: "middle"
  });

  // Multi-user input label (top-left)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.1, w: 2.5, h: 1.2,
    fill: { color: theme.primary, transparency: 10 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.1, w: 2.5, h: 0.05,
    fill: { color: theme.primary }
  });
  slide.addText("Multi-User Interaction", {
    x: 0.7, y: 4.2, w: 2.3, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });
  slide.addText("Session collection &\ntrajectory aggregation", {
    x: 0.7, y: 4.55, w: 2.3, h: 0.65,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "top"
  });

  // Arrow from multi-user → Evidence
  slide.addShape(pres.shapes.LINE, {
    x: 1.85, y: 2.5, w: 0, h: 1.6,
    line: { color: theme.primary, width: 2, dashType: "dash" }
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

