  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Cross-User Trajectory Aggregation", {
    x: 0.5, y: 0.2, w: 9, h: 0.55,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  slide.addText("Exposes Skill Behavioral Boundaries", {
    x: 0.5, y: 0.7, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, italic: true, align: "left"
  });

  // LEFT: Key insight cards stacked
  // Card 1 - Complementary signals
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.25, w: 4.6, h: 1.3,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.25, w: 0.06, h: 1.3,
    fill: { color: theme.secondary }
  });
  slide.addText("Complementary Signals", {
    x: 0.65, y: 1.3, w: 4.2, h: 0.35,
    fontSize: 16, fontFace: "Georgia",
    color: theme.secondary, bold: true, align: "left"
  });
  slide.addText("Different users exercising the same skill under diverse contexts produce complementary views — revealing both conditions where it works and where it breaks.", {
    x: 0.65, y: 1.65, w: 4.2, h: 0.8,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "top"
  });

  // Card 2 - Single-user limitation
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 2.7, w: 4.6, h: 1.3,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 2.7, w: 0.06, h: 1.3,
    fill: { color: "e76f51" }
  });
  slide.addText("Single-User Limitation", {
    x: 0.65, y: 2.75, w: 4.2, h: 0.35,
    fontSize: 16, fontFace: "Georgia",
    color: "e76f51", bold: true, align: "left"
  });
  slide.addText("A single user rarely generates enough signal to separate a generalizable improvement from an idiosyncratic fix. Cross-user aggregation is essential.", {
    x: 0.65, y: 3.1, w: 4.2, h: 0.8,
