    x: 5.2, y: 1.25, w: 4.4, h: 2.75,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.25, w: 4.4, h: 0.05,
    fill: { color: theme.accent }
  });

  slide.addText("Compatible Claw-Style Systems", {
    x: 5.4, y: 1.35, w: 4.0, h: 0.35,
    fontSize: 15, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left"
  });

