  });
  slide.addText("Grouped by\nReferenced Skill", {
    x: 3.5, y: 4.35, w: 2.5, h: 0.7,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", align: "center", valign: "middle"
  });

  slide.addText("→", {
    x: 6.05, y: 4.4, w: 0.5, h: 0.6,
    fontSize: 22, color: theme.accent, bold: true, align: "center", valign: "middle"
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.6, y: 4.35, w: 2.7, h: 0.7,
    fill: { color: theme.accent },
    rectRadius: 0.05
  });
  slide.addText("Shared Evidence Base\nfor Agentic Evolver", {
    x: 6.6, y: 4.35, w: 2.7, h: 0.7,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, align: "center", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

