// slide-08.js — Key Takeaways (Summary/Closing Page)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("Three Properties That Distinguish SkillClaw", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.light, italic: true, align: "left"
  });

  // Three takeaway cards
  const takeaways = [
    {
      num: "01",
      title: "Collective Evolution",
      desc: "Knowledge from individual interactions contributes to a shared, continuously improving skill ecosystem. Users no longer rediscover solutions independently.",
      color: theme.accent,
      x: 0.4
    },
    {
      num: "02",
      title: "Fully Automatic",
      desc: "Skill evolution is driven by runtime interaction without manual curation or explicit user intervention. The system improves itself from usage.",
      color: "2a9d8f",
      x: 3.55
    },
    {
      num: "03",
      title: "Agentic Evolution Paradigm",
      desc: "Skill updates are produced through open-ended reasoning over evidence, not predefined update rules. The evolver adapts to new patterns autonomously.",
      color: "e76f51",
      x: 6.7
    }
  ];

  takeaways.forEach((t) => {
    // Card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: t.x, y: 1.45, w: 2.85, h: 2.7,
      fill: { color: "FFFFFF", transparency: 92 },
      line: { color: t.color, width: 1.5 }
    });

    // Number
    slide.addText(t.num, {
      x: t.x + 0.2, y: 1.6, w: 0.8, h: 0.6,
      fontSize: 36, fontFace: "Georgia",
      color: t.color, bold: true, align: "left"
    });

    // Title
    slide.addText(t.title, {
      x: t.x + 0.2, y: 2.2, w: 2.45, h: 0.4,
      fontSize: 16, fontFace: "Georgia",
      color: "FFFFFF", bold: true, align: "left"
    });

    // Separator
    slide.addShape(pres.shapes.RECTANGLE, {
      x: t.x + 0.2, y: 2.6, w: 1.5, h: 0.03,
      fill: { color: t.color }
    });

    // Description
    slide.addText(t.desc, {
      x: t.x + 0.2, y: 2.7, w: 2.45, h: 1.3,
      fontSize: 12, fontFace: "Calibri",
      color: theme.light, align: "left", valign: "top"
    });
  });

  // Implications bar at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.4, w: 9.2, h: 0.85,
    fill: { color: theme.secondary, transparency: 30 }
  });

  slide.addText("Implications for Continuously Improving Agent Systems", {
    x: 0.6, y: 4.45, w: 8.8, h: 0.35,
    fontSize: 14, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("SkillClaw demonstrates that multi-user agent ecosystems can self-improve when equipped with evidence-driven, agentic skill evolution — moving beyond static tooling toward living, adaptive skill repositories.", {
    x: 0.6, y: 4.8, w: 8.8, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.light, align: "left", valign: "top"
  });

  // Source
  slide.addText("arxiv.org/abs/2604.08377", {
    x: 0.5, y: 5.35, w: 4, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: theme.light, transparency: 40, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

