    x: 0.6, y: 4.45, w: 8.8, h: 0.35,
    fontSize: 14, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("SkillClaw demonstrates that multi-user agent ecosystems can self-improve when equipped with evidence-driven, agentic skill evolution — moving beyond static tooling toward living, adaptive skill repositories.", {
    x: 0.6, y: 4.8, w: 8.8, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.light, align: "left", valign: "top"
  });

  // Source
  slide.addText("arxiv.org/abs/2604.08377", {
    x: 0.5, y: 5.35, w: 4, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: theme.light, transparency: 40, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

